package app.chataibox.mobile;
import org.json.*;import okhttp3.*;import okio.ByteString;import java.io.*;import java.net.*;import java.util.*;import java.util.concurrent.*;import android.util.Base64;
public final class MediaNetwork {
 private final Map<String,WebSocket> sockets=new ConcurrentHashMap<>();
 private OkHttpClient client(JSONObject settings)throws Exception{OkHttpClient.Builder b=new OkHttpClient.Builder().connectTimeout(20,TimeUnit.SECONDS).readTimeout(180,TimeUnit.SECONDS).callTimeout(180,TimeUnit.SECONDS).followRedirects(false);String address=settings.optString("proxy");if(!address.isEmpty()){URI p=new URI(address);b.proxy(new Proxy(Proxy.Type.HTTP,new InetSocketAddress(p.getHost(),p.getPort())));}return b.build();}
 public void cancel(String id){WebSocket s=sockets.get(id);if(s!=null)s.cancel();}
 public JSONObject edge(JSONObject args,JSONObject settings)throws Exception{URI u=new URI(args.getString("url"));JSONArray frames=args.getJSONArray("frames");if(!"wss".equals(u.getScheme())||!"api.msedgeservices.com".equals(u.getHost())||!"/tts/cognitiveservices/websocket/v1".equals(u.getPath())||frames.length()!=2)throw new IOException("Edge TTS 请求无效");for(int i=0;i<2;i++)if(frames.getString(i).length()>30000)throw new IOException("Edge TTS 请求过大");String id=args.getString("requestId");CountDownLatch done=new CountDownLatch(1);ByteArrayOutputStream audio=new ByteArrayOutputStream();String[] error={null};OkHttpClient c=client(settings);WebSocket ws=c.newWebSocket(new Request.Builder().url(u.toString()).header("Origin","chrome-extension://jdiccldimpdaibmpdkjnbmckianbfold").header("User-Agent","Mozilla/5.0 (Windows NT 10.0; Win64; x64) AppleWebKit/537.36 (KHTML, like Gecko) Chrome/143.0.0.0 Safari/537.36 Edg/143.0.0.0").build(),new WebSocketListener(){
 public void onOpen(WebSocket s,Response r){try{for(int i=0;i<2;i++)s.send(frames.getString(i));}catch(Exception e){error[0]="Edge TTS 请求失败";done.countDown();}}
 public void onMessage(WebSocket s,ByteString data){byte[] b=data.toByteArray();if(b.length<2)return;int n=((b[0]&255)<<8)|(b[1]&255);if(n+2>b.length)return;if(new String(b,2,n,java.nio.charset.StandardCharsets.UTF_8).contains("Path:audio")){audio.write(b,n+2,b.length-n-2);if(audio.size()>8*1024*1024){error[0]="Edge TTS 音频过大";done.countDown();}}}
 public void onMessage(WebSocket s,String text){if(text.contains("Path:turn.end"))done.countDown();}
 public void onFailure(WebSocket s,Throwable e,Response r){error[0]="Edge TTS 连接失败，请检查网络或代理";done.countDown();}
 public void onClosed(WebSocket s,int code,String reason){if(done.getCount()>0){error[0]="Edge TTS 连接提前结束";done.countDown();}}});sockets.put(id,ws);try{if(!done.await(90,TimeUnit.SECONDS))throw new IOException("Edge TTS 请求超时");if(error[0]!=null)throw new IOException(error[0]);if(audio.size()==0)throw new IOException("Edge TTS 未返回音频");return new JSONObject().put("base64",Base64.encodeToString(audio.toByteArray(),Base64.NO_WRAP)).put("mime","audio/mpeg");}finally{sockets.remove(id);ws.cancel();c.dispatcher().executorService().shutdown();c.connectionPool().evictAll();}}
 public JSONObject request(String method,JSONObject args,JSONObject settings)throws Exception{OkHttpClient c=client(settings);try{Request.Builder request=new Request.Builder();if(method.equals("fetchImage")){URI u=new URI(args.getString("url"));String host=u.getHost();if(!"https".equals(u.getScheme())||host==null||u.getUserInfo()!=null||host.matches("(?i)(localhost|127\\..*|10\\..*|192\\.168\\..*|169\\.254\\..*|.*:.*)"))throw new IOException("图片地址无效");request.url(u.toString());}else{JSONObject p=Providers.resolve(settings,args.optString("providerId"));byte[] data=Base64.decode(args.getString("base64"),Base64.DEFAULT);if(data.length==0||data.length>8*1024*1024)throw new IOException("音频应小于 8 MiB");boolean builtin=p.optString("id").equals("deepseek");String mime=args.optString("mime","audio/wav");MultipartBody.Builder body=new MultipartBody.Builder().setType(MultipartBody.FORM).addFormDataPart("file",mime.equals("audio/ogg")?"recording.ogg":"recording.wav",RequestBody.create(MediaType.parse(mime),data));if(!builtin)body.addFormDataPart("model",p.optString("asrModel","whisper-1"));request.url(builtin?"https://api.deepseek.com/v1/tools/asr":p.getString("baseUrl")+"/audio/transcriptions").header("Authorization","Bearer "+p.optString("apiKey")).post(body.build());}
 try(Response r=c.newCall(request.build()).execute()){if(!r.isSuccessful())throw new IOException((method.equals("asr")?"语音识别":"图片加载")+"失败（HTTP "+r.code()+"）");if(method.equals("asr")){JSONObject json=new JSONObject(r.body().string());return new JSONObject().put("text",json.getString("text"));}String mime=r.header("Content-Type","").split(";")[0];if(!mime.matches("image/(png|jpeg|webp|gif)"))throw new IOException("仅支持普通图片");ByteArrayOutputStream out=new ByteArrayOutputStream();try(InputStream in=r.body().byteStream()){byte[] b=new byte[8192];int n;while((n=in.read(b))!=-1){out.write(b,0,n);if(out.size()>8*1024*1024)throw new IOException("图片超过 8 MiB");}}return new JSONObject().put("dataUrl","data:"+mime+";base64,"+Base64.encodeToString(out.toByteArray(),Base64.NO_WRAP));}}finally{c.dispatcher().executorService().shutdown();c.connectionPool().evictAll();}}
}
